                        s.add(g[a][b]); seen[a][b]=True
                if s.issubset({0}):
                    vals={g[a][b] for a,b in [(i,j),(i+1,j),(i,j+1),(i+1,j+1)]}
                    nonzeros=[v for v in vals if v!=0]
                    if len(nonzeros)==1:
                        c=nonzeros[0]
                        out[i][j]=c; out[i+1][j]=c; out[i][j+1]=c; out[i+1][j+1]=c; changed=True
                    elif len(nonzeros)>1:
