                        mc=max(cnt,key=cnt.get); out[i][j]=mc; out[i+1][j]=mc; out[i][j+1]=mc; out[i+1][j+1]=mc; changed=True
        for i in range(H):
            for j in range(W):
                if g[i][j]==out[i][j] or seen[i][j]: continue
                s=set(); n=0
                for a in range(max(0,i-1),min(H,i+2)):
                    for b in range(max(0,j-1),min(W,j+2)):
                        if not seen[a][b]: s.add(g[a][b]); seen[a][b]=True; n+=1
                vals=s-{0}
                if not vals: continue
                cnt={}
                for v in vals: cnt[v]=cnt.get(v,0)+1
