def f(i):
    i=np.array(i); out=i.copy(); bg=8
    lb,n=ndimage.label(i!=bg, structure=np.ones((1,1)))
    for k in range(1,n+1):
        rr,cc=np.where(lb==k)
        r0,r1,c0,c1=int(rr.min()),int(rr.max()+1),int(cc.min()),int(cc.max()+1)
        s=i[r0:r1,c0:c1]; h,w=s.shape
        # minimal v period making s a vertical tiling of its top rows
        vp=None
        for p in range(1,h):
            if all(s[i,j]==s[(i-p)%p,j] for i in range(p,p+h) for j in range(w)):
                vp=p; break
        if vp is None: continue
        hp=w
        for q in range(1,w):
            if all(s[i,j]==s[i,(j-q)%q] for i in range(h) for j in range(q,q+w)):
                hp=q; break
        T=s[:vp,:hp]
        # input nonzero positions inside bbox must be covered by tile nonzero cells
        okc=all(T[i%vp,j%hp]!=0 for i in range(h) for j in range(w) if s[i,j]!=0)
        if not okc: continue
        oT=T[np.arange(h)[:,None]%vp, np.arange(w)[None,:]%hp]
        out[r0:r1,c0:c1]=oT
    return out.tolist()

